for (int dim = 0; dim < 3; ++dim) {
    float min1 = XYZAdaptorBasics::GetBoxMinC(box1, dim);
    float max1 = XYZAdaptorBasics::GetBoxMaxC(box1, dim);
    float min2 = XYZAdaptorBasics::GetBoxMinC(box2, dim);
    float max2 = XYZAdaptorBasics::GetBoxMaxC(box2, dim);

    if (box1_must_contain_box2) {
        if (min2 < min1 || max2 > max1) {
            return false;
        }
    } else {
        if (max2 < min1 || max1 < min2) {
            return false;
        }
    }

    if (!allow_point_touch) {
        if (max2 == min1 || max1 == min2) {
            return false;
        }
    }
}
return true;

